<?php require_once __DIR__.'/includes/permissions.php'; require_permission('appointments.view'); $pdo=db();$u=current_user();$error='';$services=active_services();$staff=$pdo->query('SELECT u.id,u.staff_id,u.full_name,r.code role_code,s.name service_name FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN services s ON s.id=u.service_id WHERE u.status="Active" ORDER BY u.full_name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=post('action');try{if($a==='save' && can('appointments.create')){$rid=(int)post('resident_id');$sid=(int)post('service_id');$date=(string)post('appointment_date');$time=(string)post('appointment_time');$assigned=post('assigned_staff_id')!==''?(int)post('assigned_staff_id'):null;$purpose=trim((string)post('purpose'));$vaccine=trim((string)post('vaccine_type'));if(!$rid||!$sid||!$date||!$time)throw new Exception('Resident, service, date and time are required.');$cap=(int)$pdo->prepare('SELECT daily_capacity FROM services WHERE id=?')->execute([$sid]);$q=$pdo->prepare('SELECT daily_capacity FROM services WHERE id=? AND status="Active"');$q->execute([$sid]);$cap=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*) FROM appointments WHERE service_id=? AND appointment_date=? AND status IN ("Pending","Scheduled")');$q->execute([$sid,$date]);if((int)$q->fetchColumn()>=$cap)throw new Exception('Daily capacity is full for this service.');$ref='APT-'.date('YmdHis').'-'.strtoupper(bin2hex(random_bytes(2)));$q=$pdo->prepare('INSERT INTO appointments(reference_no,resident_id,service_id,appointment_date,appointment_time,assigned_staff_id,purpose,vaccine_type,status,created_by) VALUES(?,?,?,?,?,?,?,? ,"Scheduled",?)');$q->execute([$ref,$rid,$sid,$date,$time,$assigned,$purpose,$vaccine,(int)$u['id']]);audit('APPOINTMENT_CREATE','appointments',(int)$pdo->lastInsertId(),'Appointment created');flash('success','Appointment created: '.$ref);redirect(BASE_URL.'/appointments.php');}elseif($a==='status' && can('appointments.edit')){$id=(int)post('id');$status=post('status');if(!in_array($status,['Pending','Scheduled','Completed','Cancelled','No-show'],true))throw new Exception('Invalid status.');$q=$pdo->prepare('SELECT assigned_staff_id FROM appointments WHERE id=?');$q->execute([$id]);$row=$q->fetch();if($u['role_name']!=='System Administrator' && $row && $row['assigned_staff_id']!=$u['id'])throw new Exception('You can only update appointments assigned to you.');$pdo->prepare('UPDATE appointments SET status=? WHERE id=?')->execute([$status,$id]);audit('APPOINTMENT_UPDATE','appointments',$id,'Appointment status changed to '.$status);flash('success','Appointment updated.');redirect(BASE_URL.'/appointments.php');}}catch(Throwable $e){$error=$e->getMessage();}}
$search=trim((string)get('search',''));$status=get('status','');$date=get('date','');$where=['1=1'];$params=[];if($search){$where[]='(a.reference_no LIKE ? OR r.patient_id LIKE ? OR r.first_name LIKE ? OR r.last_name LIKE ?)';$x="%$search%";array_push($params,$x,$x,$x,$x);}if($status){$where[]='a.status=?';$params[]=$status;}if($date){$where[]='a.appointment_date=?';$params[]=$date;}if($u['role_name']!=='System Administrator'){$where[]='(a.assigned_staff_id=? OR a.assigned_staff_id IS NULL)';$params[]=$u['id'];}$q=$pdo->prepare('SELECT a.*,r.patient_id,r.first_name,r.last_name,s.name service_name,us.full_name assigned_name FROM appointments a LEFT JOIN residents r ON r.id=a.resident_id JOIN services s ON s.id=a.service_id LEFT JOIN users us ON us.id=a.assigned_staff_id WHERE '.implode(' AND ',$where).' ORDER BY a.appointment_date DESC,a.appointment_time');$q->execute($params);$rows=$q->fetchAll();$residents=$pdo->query('SELECT id,patient_id,first_name,last_name FROM residents WHERE status="Active" ORDER BY last_name,first_name')->fetchAll();include __DIR__.'/includes/header.php';?><div class="page-head"><div><h1>Appointments</h1><p>Schedule, assign and monitor service appointments.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="panel mb-4"><div class="panel-head"><h5>Create Appointment</h5></div><?php if(can('appointments.create')):?><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="save"><div class="col-md-4"><label>Resident *</label><select name="resident_id" class="form-select" required><option value="">Select resident</option><?php foreach($residents as $r):?><option value="<?=$r['id']?>"><?=e($r['patient_id'].' — '.$r['last_name'].', '.$r['first_name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label>Service *</label><select name="service_id" class="form-select" required><?php foreach($services as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label>Date *</label><input name="appointment_date" type="date" class="form-control" min="<?=date('Y-m-d')?>" required></div><div class="col-md-2"><label>Time *</label><input name="appointment_time" type="time" class="form-control" required></div><div class="col-md-2"><label>Assigned Staff</label><select name="assigned_staff_id" class="form-select"><option value="">Unassigned</option><?php foreach($staff as $x):?><option value="<?=$x['id']?>"><?=e($x['full_name'].' ('.$x['staff_id'].')')?></option><?php endforeach;?></select></div><div class="col-md-8"><label>Purpose</label><input name="purpose" class="form-control"></div><div class="col-md-4"><label>Vaccine Type (if applicable)</label><input name="vaccine_type" class="form-control"></div><div class="col-12"><button class="btn btn-primary">Create Appointment</button></div></form><?php else:?><div class="alert alert-info mb-0">Your role can view appointments but cannot create them.</div><?php endif;?></div><div class="panel"><div class="panel-head"><h5>Appointment List</h5><input class="form-control table-search" placeholder="Search..." data-table-search="apptTable"></div><form class="row g-2 mb-3" method="get"><div class="col-md-5"><input class="form-control" name="search" value="<?=e($search)?>" placeholder="Reference, patient ID or name"></div><div class="col-md-3"><input class="form-control" type="date" name="date" value="<?=e($date)?>"></div><div class="col-md-2"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['Pending','Scheduled','Completed','Cancelled','No-show'] as $x):?><option <?=$status===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Filter</button></div></form><div class="table-responsive"><table class="table align-middle" id="apptTable"><thead><tr><th>Reference</th><th>Patient</th><th>Service</th><th>Date/Time</th><th>Assigned</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['reference_no'])?></td><td><?=e($r['patient_id']??'—')?><br><small><?=e(trim(($r['first_name']??'').' '.($r['last_name']??'')))?></small></td><td><?=e($r['service_name'])?></td><td><?=e($r['appointment_date'].' '.$r['appointment_time'])?></td><td><?=e($r['assigned_name']??'Unassigned')?></td><td><span class="badge status-badge"><?=e($r['status'])?></span></td><td><?php if(can('appointments.edit')):?><form method="post" class="d-flex gap-1"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" class="form-select form-select-sm"><?php foreach(['Pending','Scheduled','Completed','Cancelled','No-show'] as $x):?><option <?=$r['status']===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><button class="btn btn-sm btn-primary">Save</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/includes/footer.php'; ?>
